async function main() {
  console.log('Starting database seed from Excel data...');

  // --- Seed Installations ---
  console.log(`Seeding ${installations.length} installations...`);
  for (const inst of installations) {
    await prisma.installation.upsert({
      where: { installationId: inst.installationId },
      update: {},
      create: {
        id: inst.id,
        installationId: inst.installationId,
        location: inst.location,
        type: inst.type,
        isActive: inst.isActive,
      },
    });
  }
  console.log('  Installations seeded.');

  // --- Build installation lookup (installationId -> DB id) ---
  const allInstallations = await prisma.installation.findMany();
  const installLookup: Record<string, string> = {};
  for (const i of allInstallations) {
    installLookup[i.installationId] = i.id;
  }

  // --- Seed Equipment ---
  console.log(`Seeding ${equipmentList.length} equipment records...`);
  for (const eq of equipmentList) {
    const dbInstallId = installLookup[eq.installationId];
    if (!dbInstallId) {
      console.warn(`  Skipping equipment '${eq.equipmentTag}': installation '${eq.installationId}' not found`);
      continue;
    }
    await prisma.runningEquipmentMaster.upsert({
      where: { equipmentTag: eq.equipmentTag },
      update: {},
      create: {
        equipmentTag: eq.equipmentTag,
        category: eq.category,
        description: eq.description,
        make: eq.make,
        model: eq.model,
        installationId: dbInstallId,
        specifications: eq.specifications as any,
      },
    });
  }
  console.log('  Equipment seeded.');

  // --- Seed Instruments ---
  console.log(`Seeding ${instrumentList.length} instrument records...`);
  for (const inst of instrumentList) {
    const dbInstallId = installLookup[inst.installationId];
    if (!dbInstallId) {
      console.warn(`  Skipping instrument '${inst.tagId}': installation '${inst.installationId}' not found`);
      continue;
    }
    await prisma.instrumentMaster.upsert({
      where: { tagId: inst.tagId },
      update: {},
      create: {
        tagId: inst.tagId,
        type: inst.type,
        serviceLine: inst.serviceLine,
        description: inst.description,
        make: inst.make,
        installationId: dbInstallId,
        calibrationFreqMonths: inst.calibrationFreqMonths,
      },
    });
  }
  console.log('  Instruments seeded.');

  // --- Seed Custody Transfer Meters ---
  console.log(`Seeding ${ctmList.length} CTM records...`);
  for (const ctm of ctmList) {
    await prisma.custodyTransferMeter.upsert({
      where: { meterId: ctm.meterId },
      update: {},
      create: {
        id: ctm.id,
        meterId: ctm.meterId,
        customerId: ctm.meterId,
        customerName: ctm.customerName,
        meterType: ctm.meterType,
        product: ctm.product,
        fluidType: ctm.fluidType,
      },
    });
  }
  console.log('  CTM records seeded.');

  console.log('Database seeding complete!');
}

main()
  .then(() => prisma.$disconnect())
  .catch((e) => {
    console.error('Seed error:', e);
    prisma.$disconnect();
    process.exit(1);
  });
